import { Controller, Get, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 허용 인증기기 수는 저장할 테이블·컬럼이 없어 전역 기본값으로 둔다.
const DEFAULT_ALLOWED_DEVICE_COUNT = 1;

@Controller('api/v1')
export class FnSfr03702Controller {
  @Get('/auth-settings')
  async listAuthSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const query = checks.queryOf(req.query);
    const pageNo = Number(query['page'] ?? 0);
    const sizeRaw = Number(query['size'] ?? 20);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, 200);
    return transaction(async (db) => {
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM auth_setting', {});
      const rows = await db.query(
        'SELECT auth_setting_id AS "authSettingId", employee_id AS "employeeId", auth_target_yn AS "authTargetYn" FROM auth_setting ORDER BY auth_setting_id LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { size: size, offset: pageNo * size },
      );
      const items = rows.map((row: any) => ({
        authSettingId: Number(row.authSettingId),
        employeeId: Number(row.employeeId),
        authTargetYn: row.authTargetYn,
        allowedDeviceCount: DEFAULT_ALLOWED_DEVICE_COUNT,
      }));
      return { items: items, page: pageNo, size: size, total: Number(totalRows[0].total) };
    });
  }

  @Put('/auth-settings/:authSettingId')
  async updateAuthSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const idText = req.params['authSettingId'];
    if (typeof data['authTargetYn'] !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '2차 인증 대상 여부를 선택하세요.');
    }
    const count = data['allowedDeviceCount'];
    if (count === undefined || count === null || count === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '허용 인증기기 수를 입력하세요.');
    }
    if (typeof count !== 'number' || !Number.isInteger(count) || count < 1) {
      throw new ApiError(422, 'INVALID_ALLOWED_DEVICE_COUNT', '허용 인증기기 수는 1 이상의 정수여야 합니다.');
    }
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(404, 'AUTH_SETTING_NOT_FOUND', '인증 설정을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'UPDATE auth_setting SET auth_target_yn = :authTargetYn, updated_at = now() WHERE auth_setting_id = CAST(:id AS bigint) RETURNING auth_setting_id AS "authSettingId", auth_target_yn AS "authTargetYn"',
        { authTargetYn: data['authTargetYn'], id: idText },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'AUTH_SETTING_NOT_FOUND', '인증 설정을 찾을 수 없습니다.');
      }
      // 가정: 허용 인증기기 수를 저장할 컬럼이 없어 검증한 값을 그대로 돌려준다.
      // 가정: 기존 등록 기기는 유지하고 신규 등록만 제한한다.
      return {
        authSettingId: Number(rows[0].authSettingId),
        authTargetYn: rows[0].authTargetYn,
        allowedDeviceCount: count,
      };
    });
  }
}

