import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Tiles,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  Select,
  NumberInput,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

export default function FnSfr03702Page({ role, notify }: PageProps) {
  const [pageNo, setPageNo] = useState(0);
  const [editing, setEditing] = useState<Row | null>(null);
  const [target, setTarget] = useState('true');
  const [count, setCount] = useState<number | string>(1);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/auth-settings', role, undefined, { page: pageNo, size: 20 }),
    [pageNo],
  );

  const rows = data ? data.items : [];
  const allowed = rows.length > 0 ? rows[0]['allowedDeviceCount'] : 1;

  function openEdit(row: Row) {
    setEditing(row);
    setTarget(row['authTargetYn'] ? 'true' : 'false');
    setCount(Number(row['allowedDeviceCount'] ?? 1));
  }

  async function save() {
    if (!editing) return;
    if (count === '' || typeof count !== 'number' || !Number.isInteger(count) || count < 1) {
      throw new Error('허용 인증기기 수는 1 이상의 정수여야 합니다.');
    }
    await call('PUT', '/auth-settings/' + String(editing['authSettingId']), role, {
      authTargetYn: target === 'true',
      allowedDeviceCount: count,
    });
    notify('인증 설정을 저장했습니다.');
    setEditing(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>설정 현황</h2>
        <Tiles
          items={[
            ['설정 건수', <Num value={data ? data.total : 0} />],
            ['허용 인증기기 수', <Num value={allowed} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>인증 대상</h2>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable
          columns={[
            { key: 'employeeId', label: '임직원 ID', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'authTargetYn', label: '2차 인증 대상 여부', render: (r) => <Badge value={r['authTargetYn'] ? '대상' : '비대상'} /> },
            { key: 'allowedDeviceCount', label: '임직원 1인당 허용 인증기기 수', render: (r) => <Num value={r['allowedDeviceCount']} /> },
            { key: 'action', label: '처리', render: (r) => <button type="button" onClick={() => openEdit(r)}>설정</button> },
          ]}
          rows={rows}
          onRowClick={openEdit}
          empty="인증 설정이 없습니다."
        />
        <Pager page={pageNo} size={data ? data.size : 20} total={data ? data.total : 0} onPage={setPageNo} />
      </section>
      {editing ? (
        <Drawer title="인증 설정 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={save} submit="저장">
            <Field label="임직원 ID">
              <RefName table="employee" role={role} value={editing['employeeId']} />
            </Field>
            <Field label="2차 인증 대상 여부" required>
              <Select
                value={target}
                onChange={setTarget}
                options={[['true', '대상'], ['false', '비대상']]}
              />
            </Field>
            <Field label="허용 인증기기 수" required hint="1 이상 정수">
              <NumberInput value={count} onChange={setCount} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
